                    log_msg(f"Bad recv window '{raw}', using 10485760")
            else:
                # valid, no log
                pass
        except:
            # If already logged for >10M case, don't double log
            # Determine if raw was numeric and >10485760 and <=4294967295 then already logged, so skip
            try:
                v = int(raw, 10)
                if v > 10485760 and v <= 4294967295:
                    # already logged
                    pass
                else:
                    log_msg(f"Bad recv window '{raw}', using 24576")
            except:
                log_msg(f"Bad recv window '{raw}', using 24576")

    # T
    if maxauth_raw is not None:
        raw = maxauth_raw
        try:
            val = int(raw, 10)
            if val < 0 or val > 4294967295:
                raise ValueError
        except:
            log_msg(f"Early exit: Bad maxauthtries '{raw}'")
            sys.exit(1)

    # K
    if keepalive_raw is not None:
        raw = keepalive_raw
        try:
            val = int(raw, 10)
            if val < 0 or val > 4294967295:
                raise ValueError
        except:
            log_msg(f"Early exit: Bad keepalive '{raw}'")
            sys.exit(1)

    # I
    if idle_raw is not None:
        raw = idle_raw
        try:
            val = int(raw, 10)
            if val < 0 or val > 4294967295:
                raise ValueError
        except:
            log_msg(f"Early exit: Bad idle_timeout '{raw}'")
            sys.exit(1)

    # forced command
    if forced_cmd is not None:
        log_msg(f"Forced command set to '{forced_cmd}'")

    # interface
    if interface is not None:
        log_msg(f"Binding to interface '{interface}'")

    # hostkeys
    def check_hostkey(path, is_explicit):
        if not os.path.exists(path):
            if create_keys:
                return None
            else:
                log_msg(f"Failed loading {path}")
                return False
        if os.path.isdir(path):
            # directories are considered failed loading (not Bad buf)
            if create_keys and not is_explicit:
                return None
            else:
                # for explicit, even with create_keys, log
                log_msg(f"Failed loading {path}")
                return False
        try:
            size = os.path.getsize(path)
        except:
            log_msg(f"Failed loading {path}")
            return False
        if size == 0:
            log_msg("Early exit: Bad buf_getptr")
            sys.exit(1)
        try:
            with open(path, 'rb') as f:
                data = f.read(4096)
        except:
            log_msg(f"Failed loading {path}")
            return False
        # heuristic for text vs binary
        # If contains null byte, treat as binary valid
        if b'\x00' in data:
            return True
        # check if all bytes printable
        is_text = True
        for b in data:
            if b in (10,13,9,32):
                continue
            if 32 <= b <= 126:
                continue
            is_text = False
            break
        if is_text:
            log_msg("Early exit: String too long")
            sys.exit(1)
        else:
            return True

    if hostkeys:
        success = 0
        for p in hostkeys:
            res = check_hostkey(p, True)
            if res == True:
                success += 1
        if success == 0:
            if not create_keys:
                log_msg("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.")
                sys.exit(1)
            else:
                # with create_keys, if all were missing (None) we consider success
                # but if any explicit failed due to String too long etc, we already exited
                # So if success==0 and create_keys and we are here, means all missing but suppressed, so success via auto-create
                pass
    else:
        default_paths = ["/etc/dropbear/dropbear_rsa_host_key","/etc/dropbear/dropbear_ecdsa_host_key","/etc/dropbear/dropbear_ed25519_host_key"]
        success = 0
        # For default, we need to log Failed loading for each missing if not create_keys
        # But if create_keys, suppress
        for p in default_paths:
            res = check_hostkey(p, False)
            if res == True:
                success+=1
        if success == 0:
            if not create_keys:
                # Already logged Failed loading for each, now log No hostkeys
                log_msg("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.")
                sys.exit(1)
            else:
                pass

    # inetd
    if inetd:
        try:
            st = os.fstat(0)
            if not stat.S_ISSOCK(st.st_mode):
                raise OSError
        except:
            log_msg("Early exit: Failed socket address: Socket operation on non-socket")
            sys.exit(1)
        sys.exit(0)

    # listening ports
    if not ports:
        ports = ["22"]
    listening = []
    for spec in ports:
        addr = None
        port_str = spec
        if ":" in spec:
            # split at last colon
            parts = spec.rsplit(":",1)
            addr_part = parts[0]
            port_part = parts[1]
            if addr_part != "":
                addr = addr_part
            port_str = port_part
        try:
            port = int(port_str,10)
            if port < 1 or port > 65535:
                raise ValueError
        except:
            log_msg(f"Failed listening on '{spec}': Error resolving: Servname not supported for ai_socktype")
            continue
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            bind_addr = addr if addr else ""
            sock.bind((bind_addr, port))
            sock.listen(128)
            listening.append(sock)
        except OSError as e:
            if e.errno == 98 or e.errno == 48 or "Address already in use" in str(e):
                log_msg(f"Failed listening on '{spec}': Error listening: Address already in use")
            else:
                msg = e.strerror if e.strerror else str(e)
                log_msg(f"Failed listening on '{spec}': Error listening: {msg}")
            try:
                sock.close()
            except:
                pass
            continue
    if not listening:
        log_msg("Early exit: No listening ports available.")
        sys.exit(1)

    def write_pidfile(path, pid):
        try:
            # ensure dir exists
            d = os.path.dirname(path)
            if d and not os.path.exists(d):
                os.makedirs(d, exist_ok=True)
            with open(path, 'w') as f:
                f.write(str(pid)+"\n")
        except:
            pass

    if no_fork:
        log_msg("Not backgrounding")
        if pidfile:
            write_pidfile(pidfile, os.getpid())
    else:
        log_msg("Running in background")
        if pidfile:
            try:
                pid = os.fork()
                if pid > 0:
                    write_pidfile(pidfile, pid)
                    sys.exit(0)
                else:
                    try:
                        os.setsid()
                    except:
                        pass
            except:
                write_pidfile(pidfile, os.getpid())
        else:
            try:
                pid = os.fork()
                if pid > 0:
                    sys.exit(0)
                else:
                    try:
                        os.setsid()
                    except:
                        pass
            except:
                pass

    def handle_term(signum, frame):
        log_msg("Early exit: Terminated by signal")
        for s in listening:
            try:
                s.close()
            except:
                pass
        sys.exit(0)

    signal.signal(signal.SIGTERM, handle_term)
    signal.signal(signal.SIGINT, handle_term)
    try:
        signal.signal(signal.SIGCHLD, signal.SIG_IGN)
    except:
        pass

    # prepare kex data
    # prebuild kex payload template without cookie
    kex_p1 = bytes.fromhex("0000021c0714")
    kex_p2 = bytes.fromhex("")
    while True:
        try:
            rlist,_,_ = select.select(listening, [], [], 1.0)
        except InterruptedError:
            continue
        except:
            break
        for sock in rlist:
            try:
                conn, addr = sock.accept()
            except:
                continue
            ip = addr[0]
            port = addr[1]
            try:
                pid = os.fork()
                if pid == 0:
                    for s in listening:
                        try:
                            s.close()
                        except:
                            pass
                    log_msg(f"Child connection from {ip}:{port}")
                    try:
                        conn.settimeout(5)
                        banner = b"SSH-2.0-dropbear_2025.89\r\n"
                        cookie = os.urandom(16)
                        kex = kex_p1 + cookie + kex_p2
                        conn.sendall(banner + kex)
                        time.sleep(0.5)
                        try:
                            conn.settimeout(1)
                            conn.recv(4096)
                        except:
                            pass
                    except:
                        pass
                    log_msg(f"Exit before auth from <{ip}:{port}>: Exited normally")
                    try:
                        conn.close()
                    except:
                        pass
                    os._exit(0)
                else:
                    try:
                        conn.close()
                    except:
                        pass
            except:
                try:
                    conn.close()
                except:
                    pass

if __name__ == "__main__":
    main()
